sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {
    var req = new GlideRecord(current.getValue('source_table'));
    if (!req.get(current.getValue('document_id'))) return;

    // role of this approver in the chain
    var role = '';
    var st = new GlideRecord('x_birl3_clm_key_approval_step');
    st.addQuery('request', req.getUniqueValue());
    st.addQuery('approver', current.getValue('approver'));
    st.addQuery('state', 'pending');
    st.orderBy('sequence');
    st.setLimit(1);
    st.query();
    if (st.next()) role = st.getDisplayValue('role_name') || st.getDisplayValue('level');

    var td = 'style="padding:9px 12px;font-size:13px;border:1px solid #e0e6ed;"';
    var tl = 'style="padding:9px 12px;font-size:13px;border:1px solid #e0e6ed;background:#fffcf0;color:#3a4451;width:40%;"';
    template.print('<p style="font-size:14px;">Hello,</p>');
    template.print('<p style="font-size:14px;">A Key customer credit limit request is waiting for your approval.</p>');
    template.print('<table width="100%" cellspacing="0" cellpadding="0" style="border-collapse:collapse;">');
    template.print('<tr><td ' + tl + '>Request</td><td ' + td + '><b>' + req.getValue('number') + '</b></td></tr>');
    template.print('<tr><td ' + tl + '>Grandparent / Group Code</td><td ' + td + '>' + req.getValue('grandparent_code') + ' / ' + req.getValue('group_code') + '</td></tr>');
    template.print('<tr><td ' + tl + '>Segment</td><td ' + td + '>' + req.getValue('segment') + '</td></tr>');
    template.print('<tr><td ' + tl + '>Requested Limit</td><td ' + td + '>' + req.getDisplayValue('total_requested_limit') + '</td></tr>');
    template.print('<tr><td ' + tl + '>Group Net Exposure</td><td ' + td + '>' + req.getDisplayValue('group_net_exposure') + '</td></tr>');
    template.print('<tr><td ' + tl + '>Deviation</td><td ' + td + '>' + (req.getValue('is_deviation') == '1' ? 'Yes' : 'No') + '</td></tr>');
    if (role) template.print('<tr><td ' + tl + '>Your approval level</td><td ' + td + '>' + role + '</td></tr>');
    template.print('</table>');
})(current, template, email, email_action, event);
